#include "thinkercad/circuit.hpp"
#include <iostream>
#include <stdexcept>
#include <cmath>
using namespace thinkercad;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
int main(){
    CircuitDocument doc;doc.part("board").model="arduino-uno";Esp8266Board board;board.configure("arduino-uno");board.pinMode(2,PinMode::Output);board.pinMode(3,PinMode::Input);const auto sensor=doc.addPart(PartKind::Module,200,0);doc.part(sensor).model="hcsr04";doc.part(sensor).parameters["distance"]=100;doc.connect({sensor,"VCC"},{"board","5V"});doc.connect({sensor,"GND"},{"board","GND"});doc.connect({sensor,"TRIG"},{"board","D2"});doc.connect({sensor,"ECHO"},{"board","D3"});TransientSimulation transient;const TransientSimulation::Boards boards{{"board",&board}};
    auto state=transient.evaluate(doc,boards);require(state.level({"board","D3"})==Level::Low,"powered echo starts low");board.digitalWrite(2,true);transient.evaluate(doc,boards);transient.advance(doc,boards,5);board.digitalWrite(2,false);state=transient.evaluate(doc,boards);require(transient.pulse(doc,state,boards,"board",3,true,10000).first==0,"short trigger produces no echo");
    transient.advance(doc,boards,100);board.digitalWrite(2,true);transient.evaluate(doc,boards);transient.advance(doc,boards,110);board.digitalWrite(2,false);state=transient.evaluate(doc,boards);const auto measurement=transient.pulse(doc,state,boards,"board",3,true,10000);require(measurement.first==5831&&measurement.second==6031,"round-trip distance determines pulse and elapsed wait");require(transient.pulse(doc,state,boards,"board",3,true,1000).first==0,"pulse timeout includes waiting for both edges");
    std::vector<Microseconds> high,low;transient.advance(doc,boards,measurement.second+110,[&](auto at,const auto& sample){if(sample.level({"board","D3"})==Level::High)high.push_back(at);else low.push_back(at);});require(!high.empty()&&high.front()==310&&low.back()==6141,"logic samples capture exact rise and fall timestamps");require(transient.evaluate(doc,boards).level({"board","D3"})==Level::Low,"echo returns low");
    board.digitalWrite(2,true);transient.evaluate(doc,boards);transient.advance(doc,boards,6151);board.digitalWrite(2,false);state=transient.evaluate(doc,boards);require(transient.pulse(doc,state,boards,"board",3,true,10000).first==0,"minimum retrigger period prevents overlapping echoes");
    doc.clearWires();doc.part("board").model="esp8266";board.configure("esp8266");board.pinMode(2,PinMode::Output);board.pinMode(3,PinMode::Input);const auto supply=doc.addPart(PartKind::PowerSupply,400,0),upper=doc.addPart(PartKind::Resistor,300,100),lower=doc.addPart(PartKind::Resistor,300,200);doc.part(supply).value=5;doc.part(upper).value=1000;doc.part(lower).value=2000;doc.connect({supply,"+"},{sensor,"VCC"});doc.connect({supply,"-"},{"board","GND"});doc.connect({sensor,"GND"},{"board","GND"});doc.connect({sensor,"TRIG"},{"board","GPIO2"});doc.connect({sensor,"ECHO"},{upper,"1"});doc.connect({upper,"2"},{lower,"1"});doc.connect({lower,"1"},{"board","GPIO3"});doc.connect({lower,"2"},{"board","GND"});TransientSimulation divider;divider.evaluate(doc,boards);board.digitalWrite(2,true);divider.evaluate(doc,boards);divider.advance(doc,boards,10);board.digitalWrite(2,false);state=divider.evaluate(doc,boards);require(divider.pulse(doc,state,boards,"board",3,true,10000).first==5831,"pulse measurement follows actual voltage divider into a 3.3 V GPIO");
    std::cout<<"HC-SR04 trigger width, round-trip echo edges, voltage divider, pulse timeout and retrigger checks passed\n";
}
